<section class="page-title"><div><p class="eyebrow">DÉCOUVRIR</p><h1>Catalogue des formations</h1><p>Développez vos compétences avec les parcours IFMAP.</p></div></section><div class="filter-chips"><button class="active">Toutes</button><button>Présentiel</button><button>En ligne</button><button>Mixte</button></div><div class="course-grid catalog-grid"><?php foreach($courses as $course): ?><article class="course-card"><div class="course-cover <?= htmlspecialchars($course['color']) ?>"><span class="course-cat"><?= htmlspecialchars($course['category']) ?></span><i data-icon="book"></i></div><div class="course-body"><h3><?= htmlspecialchars($course['title']) ?></h3><p>Par <?= htmlspecialchars($course['teacher']) ?></p><div class="course-meta"><span><i data-icon="play"></i><?= (int)$course['lessons'] ?> leçons</span><span><i data-icon="clock"></i><?= htmlspecialchars($course['duration']) ?></span></div><?php if($course['enrolled']): ?><a href="/academie/formation?course=<?= $course['id'] ?>" class="btn secondary wide">Ouvrir le cours</a><?php else: ?><form method="post" action="/academie/inscrire"><input type="hidden" name="course_id" value="<?= $course['id'] ?>"><button class="btn primary wide">S’inscrire au cours</button></form><?php endif ?></div></article><?php endforeach ?></div>
